    checkCudaErrors(hipFree(dTemp));
}

/*
    Because a 2D gaussian mask is symmetry in row and column,
    here only generate a 1D mask, and use the product by row
    and column index later.

    1D gaussian distribution :
        g(x, d) -- C * exp(-x^2/d^2), C is a constant amplifier

    parameters:
    og - output gaussian array in global memory
    delta - the 2nd parameter 'd' in the above function
    radius - half of the filter size
             (total filter size = 2 * radius + 1)
*/
extern "C" void updateGaussian(float delta, int radius)
{
    float fGaussian[64];

    for (int i = 0; i < 2 * radius + 1; ++i) {
        float x      = (float)(i - radius);
        fGaussian[i] = expf(-(x * x) / (2 * delta * delta));
    }

    checkCudaErrors(cudaMemcpyToSymbol(cGaussian, fGaussian, sizeof(float) * (2 * radius + 1)));
}

/*
    Perform 2D bilateral filter on image using CUDA

    Parameters:
    d_dest - pointer to destination image in device memory
    width  - image width
    height - image height
    e_d    - euclidean delta
    radius - filter radius
    iterations - number of iterations
*/

// RGBA version
extern "C" double bilateralFilterRGBA(uint               *dDest,
                                      int                 width,
                                      int                 height,
                                      float               e_d,
                                      int                 radius,
                                      int                 iterations,
                                      StopWatchInterface *timer)
{
    // var for kernel computation timing
    double dKernelTime;

    for (int i = 0; i < iterations; i++) {
        // sync host and start kernel computation timer
        dKernelTime = 0.0;
        checkCudaErrors(hipDeviceSynchronize());
        sdkResetTimer(&timer);

        dim3 gridSize((width + 16 - 1) / 16, (height + 16 - 1) / 16);
        dim3 blockSize(16, 16);

        if (iterations > 1) {
            d_bilateral_filter<<<gridSize, blockSize, 0, 0>>>(dDest, width, height, e_d, radius, rgbaTexdTemp);
        }
        else {
            d_bilateral_filter<<<gridSize, blockSize, 0, 0>>>(dDest, width, height, e_d, radius, rgbaTexdImage);
        }

        // sync host and stop computation timer
        checkCudaErrors(hipDeviceSynchronize());
        dKernelTime += sdkGetTimerValue(&timer);

        if (iterations > 1) {
            // copy result back from global memory to array
            checkCudaErrors(cudaMemcpy2D(
                dTemp, pitch, dDest, sizeof(int) * width, sizeof(int) * width, height, hipMemcpyDeviceToDevice));
        }
    }

    return ((dKernelTime / 1000.) / (double)iterations);
}

