    spPreprocess2D_kernel<<<iDivUp(threadCount, BLOCKDIM), BLOCKDIM>>>((fComplex *)d_Dst,
                                                                       (fComplex *)d_Src,
                                                                       DY,
                                                                       DX,
                                                                       threadCount,
                                                                       padding,
                                                                       (float)phaseBase
#if (USE_TEXTURE)
                                                                       ,
                                                                       texComplex
#endif
    );
    getLastCudaError("spPreprocess2D_kernel<<<>>> execution failed\n");

#if (USE_TEXTURE)
