{
    bool retval = false;

    // currently signals up to a length of 2^20 supported
    for (unsigned int i = 0; i < 20; ++i) {
        if (len == (1 << i)) {
            *levels = i;
            retval  = true;
            break;
        }
    }

    return retval;
}

