                                          uint3   gridSizeShift,
                                          uint3   gridSizeMask,
                                          float3  voxelSize,
                                          float   isoValue,
                                          uint    activeVoxels,
                                          uint    maxVerts)
{
    generateTriangles2<<<grid, NTHREADS, 0, 0>>>(pos,
                                           norm,
                                           compactedVoxelArray,
                                           numVertsScanned,
                                           volume,
                                           gridSize,
                                           gridSizeShift,
                                           gridSizeMask,
                                           voxelSize,
                                           isoValue,
                                           activeVoxels,
                                           maxVerts,
