static void resizeBGRplanarBatchCore(float       *dpSrc,
                                     int          nSrcPitch,
                                     int          nSrcWidth,
                                     int          nSrcHeight,
                                     float       *dpDst,
                                     int          nDstPitch,
                                     int          nDstWidth,
                                     int          nDstHeight,
                                     int          nBatchSize,
                                     hipStream_t stream,
                                     bool         whSameResizeRatio,
                                     int          cropX,
                                     int          cropY,
                                     int          cropW,
                                     int          cropH)
{
