void VolumeRender_setTextureFilterMode(bool bLinearFilter, Volume *vol)
{
    if (vol->volumeTex) {
        checkCudaErrors(cudaDestroyTextureObject(vol->volumeTex));
    }
    cudaResourceDesc texRes;
    memset(&texRes, 0, sizeof(cudaResourceDesc));

    texRes.resType         = cudaResourceTypeArray;
    texRes.res.array.array = vol->content;

    cudaTextureDesc texDescr;
    memset(&texDescr, 0, sizeof(cudaTextureDesc));

    texDescr.normalizedCoords = true;
    texDescr.filterMode       = bLinearFilter ? cudaFilterModeLinear : cudaFilterModePoint;

    texDescr.addressMode[0] = cudaAddressModeWrap;
    texDescr.addressMode[1] = cudaAddressModeWrap;
    texDescr.addressMode[2] = cudaAddressModeWrap;

    texDescr.readMode = VolumeTypeInfo<VolumeType>::readMode;

    checkCudaErrors(cudaCreateTextureObject(&vol->volumeTex, &texRes, &texDescr, NULL));
}

static unsigned int iDivUp(size_t a, size_t b)
{
    size_t val = (a % b != 0) ? (a / b + 1) : (a / b);
    if (val > UINT_MAX) {
        fprintf(stderr, "\nUINT_MAX limit exceeded in iDivUp() exiting.....\n");
        exit(EXIT_FAILURE); // val exceeds limit
    }

    return static_cast<unsigned int>(val);
}

void VolumeRender_updateTF(int tfIdx, int numColors, float4 *colors)
{
    if (d_transferFunc) {
        checkCudaErrors(cudaFreeArray(d_transferFunc));
        d_transferFunc = 0;
    }

    cudaChannelFormatDesc channelFloat4 = cudaCreateChannelDesc<float4>();
    checkCudaErrors(cudaMallocArray(&d_transferFunc, &channelFloat4, numColors, 1));
    checkCudaErrors(
        cudaMemcpy2DToArray(d_transferFunc, 0, 0, colors, 0, sizeof(float4) * numColors, 1, hipMemcpyHostToDevice));

    cudaResourceDesc texRes;
    memset(&texRes, 0, sizeof(cudaResourceDesc));

    texRes.resType         = cudaResourceTypeArray;
    texRes.res.array.array = d_transferFunc;

    cudaTextureDesc texDescr;
    memset(&texDescr, 0, sizeof(cudaTextureDesc));

    texDescr.normalizedCoords = true;
    texDescr.filterMode       = cudaFilterModeLinear;
    texDescr.addressMode[0]   = cudaAddressModeClamp;
    texDescr.readMode         = cudaReadModeElementType;

    checkCudaErrors(cudaCreateTextureObject(&transferTex, &texRes, &texDescr, NULL));

    if (tfIdx < 0 || tfIdx >= VOLUMERENDER_TFS) {
        return;
    }

    {
        cudaExtent extent = {VOLUMERENDER_TF_PREINTSTEPS, 0, 0};
        dim3       blockSize(32, 1, 1);
        dim3       gridSize(iDivUp(extent.width, blockSize.x), 1, 1);
        d_integrate_trapezoidal<<<gridSize, blockSize, 0, 0>>>(extent, transferTex, transferIntegrateSurf);
    }

    {
        cudaExtent extent = {VOLUMERENDER_TF_PREINTSIZE, VOLUMERENDER_TF_PREINTSIZE, VOLUMERENDER_TFS};
        dim3       blockSize(16, 16, 1);
        dim3       gridSize(iDivUp(extent.width, blockSize.x), iDivUp(extent.height, blockSize.y), 1);
        d_preintegrate<<<gridSize, blockSize, 0, 0>>>(tfIdx,
                                                float(VOLUMERENDER_TF_PREINTSTEPS),
                                                extent,
                                                transferTex,
                                                transferIntegrateTex,
                                                transferLayerPreintSurf);
    }
}

