}

bool areAlmostEqual(float a, float b, float maxRelDiff)
{
    float diff    = fabsf(a - b);
    float abs_a   = fabsf(a);
    float abs_b   = fabsf(b);
    float largest = abs_a > abs_b ? abs_a : abs_b;

    if (diff <= largest * maxRelDiff) {
        return true;
    }
    else {
        printf("maxRelDiff = %.8e\n", maxRelDiff);
        printf("diff %.8e > largest * maxRelDiff %.8e therefore %.8e and %.8e are not "
               "same\n",
               diff,
               largest * maxRelDiff,
               a,
               b);
        return false;
    }
}

int main(int argc, char **argv)
{
    int         N = 0, nz = 0, *I = NULL, *J = NULL;
    float      *val = NULL;
    const float tol = 1e-5f;
    float      *x;
    float      *rhs;
    float       r1;
    float      *r, *p, *Ax;
    cudaEvent_t start, stop;

    printf("Starting [%s]...\n", sSDKname);

    // This will pick the best possible CUDA capable device
    cudaDeviceProp deviceProp;
    int            devID = findCudaDevice(argc, (const char **)argv);
    checkCudaErrors(cudaGetDeviceProperties(&deviceProp, devID));

    if (!deviceProp.managedMemory) {
        // This sample requires being run on a device that supports Unified Memory
        fprintf(stderr, "Unified Memory not supported on this device\n");
        exit(EXIT_WAIVED);
    }

    // This sample requires being run on a device that supports Cooperative Kernel
    // Launch
    if (!deviceProp.cooperativeLaunch) {
        printf("\nSelected GPU (%d) does not support Cooperative Kernel Launch, "
               "Waiving the run\n",
               devID);
        exit(EXIT_WAIVED);
    }

    // Statistics about the GPU device
    printf("> GPU device has %d Multi-Processors, SM %d.%d compute capabilities\n\n",
           deviceProp.multiProcessorCount,
           deviceProp.major,
           deviceProp.minor);

    /* Generate a random tridiagonal symmetric matrix in CSR format */
    N  = 1048576;
    nz = (N - 2) * 3 + 4;

    cudaMallocManaged(reinterpret_cast<void **>(&I), sizeof(int) * (N + 1));
    cudaMallocManaged(reinterpret_cast<void **>(&J), sizeof(int) * nz);
    cudaMallocManaged(reinterpret_cast<void **>(&val), sizeof(float) * nz);

    genTridiag(I, J, val, N, nz);

    cudaMallocManaged(reinterpret_cast<void **>(&x), sizeof(float) * N);
    cudaMallocManaged(reinterpret_cast<void **>(&rhs), sizeof(float) * N);

    double *dot_result;

    cudaMallocManaged(reinterpret_cast<void **>(&dot_result), sizeof(double));

    *dot_result = 0.0;

    // temp memory for CG
    checkCudaErrors(cudaMallocManaged(reinterpret_cast<void **>(&r), N * sizeof(float)));
    checkCudaErrors(cudaMallocManaged(reinterpret_cast<void **>(&p), N * sizeof(float)));
    checkCudaErrors(cudaMallocManaged(reinterpret_cast<void **>(&Ax), N * sizeof(float)));

    cudaDeviceSynchronize();

    checkCudaErrors(cudaEventCreate(&start));
    checkCudaErrors(cudaEventCreate(&stop));

#if ENABLE_CPU_DEBUG_CODE
    float *Ax_cpu = reinterpret_cast<float *>(malloc(sizeof(float) * N));
    float *r_cpu  = reinterpret_cast<float *>(malloc(sizeof(float) * N));
    float *p_cpu  = reinterpret_cast<float *>(malloc(sizeof(float) * N));
    float *x_cpu  = reinterpret_cast<float *>(malloc(sizeof(float) * N));

    for (int i = 0; i < N; i++) {
        r_cpu[i]  = 1.0;
        Ax_cpu[i] = x_cpu[i] = 0.0;
    }

#endif

    for (int i = 0; i < N; i++) {
        r[i] = rhs[i] = 1.0;
        x[i]          = 0.0;
    }

    void *kernelArgs[] = {
        (void *)&I,
        (void *)&J,
        (void *)&val,
        (void *)&x,
        (void *)&Ax,
        (void *)&p,
        (void *)&r,
        (void *)&dot_result,
        (void *)&nz,
        (void *)&N,
        (void *)&tol,
    };

    int sMemSize       = sizeof(double) * ((THREADS_PER_BLOCK / 32) + 1);
    int numBlocksPerSm = 0;
    int numThreads     = THREADS_PER_BLOCK;

    checkCudaErrors(
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&numBlocksPerSm, gpuConjugateGradient, numThreads, sMemSize));

    int  numSms = deviceProp.multiProcessorCount;
    dim3 dimGrid(numSms * numBlocksPerSm, 1, 1), dimBlock(THREADS_PER_BLOCK, 1, 1);
    checkCudaErrors(cudaEventRecord(start, 0));
    checkCudaErrors(
        cudaLaunchCooperativeKernel((void *)gpuConjugateGradient, dimGrid, dimBlock, kernelArgs, sMemSize, NULL));
    checkCudaErrors(cudaEventRecord(stop, 0));
    checkCudaErrors(cudaDeviceSynchronize());

    float time;
    checkCudaErrors(cudaEventElapsedTime(&time, start, stop));

    r1 = *dot_result;

    printf("GPU Final, residual = %e, kernel execution time = %f ms\n", sqrt(r1), time);

#if ENABLE_CPU_DEBUG_CODE
    cpuConjugateGrad(I, J, val, x_cpu, Ax_cpu, p_cpu, r_cpu, nz, N, tol);
#endif

    float rsum, diff, err = 0.0;

    for (int i = 0; i < N; i++) {
        rsum = 0.0;

        for (int j = I[i]; j < I[i + 1]; j++) {
            rsum += val[j] * x[J[j]];
        }

        diff = fabs(rsum - rhs[i]);

        if (diff > err) {
            err = diff;
        }
    }

    checkCudaErrors(cudaFree(I));
    checkCudaErrors(cudaFree(J));
    checkCudaErrors(cudaFree(val));
    checkCudaErrors(cudaFree(x));
    checkCudaErrors(cudaFree(rhs));
    checkCudaErrors(cudaFree(r));
    checkCudaErrors(cudaFree(p));
    checkCudaErrors(cudaFree(Ax));
    checkCudaErrors(cudaFree(dot_result));
    checkCudaErrors(cudaEventDestroy(start));
    checkCudaErrors(cudaEventDestroy(stop));

#if ENABLE_CPU_DEBUG_CODE
    free(Ax_cpu);
    free(r_cpu);
    free(p_cpu);
    free(x_cpu);
#endif

    printf("Test Summary:  Error amount = %f \n", err);
    fprintf(stdout, "&&&& conjugateGradientMultiBlockCG %s\n", (sqrt(r1) < tol) ? "PASSED" : "FAILED");
    exit((sqrt(r1) < tol) ? EXIT_SUCCESS : EXIT_FAILURE);
}

