    if ((data[blockDim.x * blockIdx.x + threadIdx.x] != expectedVal) && (!errorFound)) {
        printf("Consumer FOUND:%d expected: %d at %d for trial %d %d\n",
               data[blockDim.x * blockIdx.x + threadIdx.x],
               expectedVal,
               (blockDim.x * blockIdx.x + threadIdx.x),
               frameNumber,
               numErrors);
        numErrors++;
        errorFound = 1;
        return;
    }
}

