////////////////////////////////////////////////////////////////////////////////
//! Initialize variables and memory for result
//! @param  result handles to memory
//! @param  matrix_size  size of the matrix
////////////////////////////////////////////////////////////////////////////////
void initResultDataLargeMatrix(ResultDataLarge &result, const unsigned int mat_size)
{
    // helper variables to initialize memory
    unsigned int zero        = 0;
    unsigned int mat_size_f  = sizeof(float) * mat_size;
    unsigned int mat_size_ui = sizeof(unsigned int) * mat_size;

    float        *tempf  = (float *)malloc(mat_size_f);
    unsigned int *tempui = (unsigned int *)malloc(mat_size_ui);

    for (unsigned int i = 0; i < mat_size; ++i) {
        tempf[i]  = 0.0f;
        tempui[i] = 0;
    }

    // number of intervals containing only one eigenvalue after the first step
    checkCudaErrors(hipMalloc((void **)&result.g_num_one, sizeof(unsigned int)));
    checkCudaErrors(hipMemcpy(result.g_num_one, &zero, sizeof(unsigned int), hipMemcpyHostToDevice));

    // number of (thread) blocks of intervals with multiple eigenvalues after
    // the first iteration
    checkCudaErrors(hipMalloc((void **)&result.g_num_blocks_mult, sizeof(unsigned int)));
    checkCudaErrors(hipMemcpy(result.g_num_blocks_mult, &zero, sizeof(unsigned int), hipMemcpyHostToDevice));

    checkCudaErrors(hipMalloc((void **)&result.g_left_one, mat_size_f));
    checkCudaErrors(hipMalloc((void **)&result.g_right_one, mat_size_f));
    checkCudaErrors(hipMalloc((void **)&result.g_pos_one, mat_size_ui));

    checkCudaErrors(hipMalloc((void **)&result.g_left_mult, mat_size_f));
    checkCudaErrors(hipMalloc((void **)&result.g_right_mult, mat_size_f));
    checkCudaErrors(hipMalloc((void **)&result.g_left_count_mult, mat_size_ui));
    checkCudaErrors(hipMalloc((void **)&result.g_right_count_mult, mat_size_ui));

    checkCudaErrors(hipMemcpy(result.g_left_one, tempf, mat_size_f, hipMemcpyHostToDevice));
    checkCudaErrors(hipMemcpy(result.g_right_one, tempf, mat_size_f, hipMemcpyHostToDevice));
    checkCudaErrors(hipMemcpy(result.g_pos_one, tempui, mat_size_ui, hipMemcpyHostToDevice));

    checkCudaErrors(hipMemcpy(result.g_left_mult, tempf, mat_size_f, hipMemcpyHostToDevice));
    checkCudaErrors(hipMemcpy(result.g_right_mult, tempf, mat_size_f, hipMemcpyHostToDevice));
    checkCudaErrors(hipMemcpy(result.g_left_count_mult, tempui, mat_size_ui, hipMemcpyHostToDevice));
    checkCudaErrors(hipMemcpy(result.g_right_count_mult, tempui, mat_size_ui, hipMemcpyHostToDevice));

    checkCudaErrors(hipMalloc((void **)&result.g_blocks_mult, mat_size_ui));
    checkCudaErrors(hipMemcpy(result.g_blocks_mult, tempui, mat_size_ui, hipMemcpyHostToDevice));
    checkCudaErrors(hipMalloc((void **)&result.g_blocks_mult_sum, mat_size_ui));
    checkCudaErrors(hipMemcpy(result.g_blocks_mult_sum, tempui, mat_size_ui, hipMemcpyHostToDevice));

    checkCudaErrors(hipMalloc((void **)&result.g_lambda_mult, mat_size_f));
    checkCudaErrors(hipMemcpy(result.g_lambda_mult, tempf, mat_size_f, hipMemcpyHostToDevice));
    checkCudaErrors(hipMalloc((void **)&result.g_pos_mult, mat_size_ui));
    checkCudaErrors(hipMemcpy(result.g_pos_mult, tempf, mat_size_ui, hipMemcpyHostToDevice));
}

////////////////////////////////////////////////////////////////////////////////
//! Cleanup result memory
//! @param result  handles to memory
////////////////////////////////////////////////////////////////////////////////
void cleanupResultDataLargeMatrix(ResultDataLarge &result)
{
    checkCudaErrors(hipFree(result.g_num_one));
