    float totalTime = 0;

    for (unsigned int i = 0; i < numIterations; i++) {
        // reset data before sort
        d_keys = h_keys;

        if (!keysOnly)
            d_values = h_values;

        checkCudaErrors(hipEventRecord(start_event, 0));

        if (keysOnly)
