    checkCudaErrors(cudaDeviceSynchronize());

    StopWatchInterface *timer = NULL;
    sdkCreateTimer(&timer);
    sdkStartTimer(&timer);

    // execute the kernel
    transformKernel<<<dimGrid, dimBlock, 0>>>(d_data, width, tex);

    // check if kernel execution generated an error
