    else if (opts.typeA == CUDA_R_8F_E5M2 && opts.typeB == CUDA_R_8F_E4M3 && opts.typeD == CUDA_R_32F)
    {
        if (deviceSupportsFp8())
        {
            run_matmul_ag<__nv_fp8_e5m2, __nv_fp8_e4m3, float>(opts);
