                                          workspacePref,
                                          &workspaceSizeEstimate));


    void *work = nullptr;
    cutensorPlan_t plan;
    uint64_t currentWorkspace = 0;

    /**********************
     * Run
     **********************/

    double minTimeCUTENSOR = 1e100;
    for (int i=0; i < incCount + 1; ++i) // last iteration will hit the cache
    {

