  // Get max output size per chunk
  size_t max_out_bytes;
  gdeflate::compressCPUGetMaxOutputChunkSize(chunk_size, &max_out_bytes);
  assert(max_out_bytes > 0);

  // Allocate and prepare output/compressed batch
  BatchDataCPU compressed_data_cpu(max_out_bytes, chunk_count);

  // Compress on the CPU using gdeflate CPU batched API
  gdeflate::compressCPU(
      input_data_cpu.ptrs(),
      input_data_cpu.sizes(),
      chunk_size,
      chunk_count,
      compressed_data_cpu.ptrs(),
      compressed_data_cpu.sizes());

  // compute compression ratio
  size_t* compressed_sizes_host = compressed_data_cpu.sizes();
  size_t comp_bytes = 0;
  for (size_t i = 0; i < chunk_count; ++i)
    comp_bytes += compressed_sizes_host[i];

  std::cout << "comp_size: " << comp_bytes
            << ", compressed ratio: " << std::fixed << std::setprecision(2)
            << (double)total_bytes / comp_bytes << std::endl;

  // Decompression options
  nvcompBatchedGdeflateDecompressOpts_t decompress_opts = nvcompBatchedGdeflateDecompressDefaultOpts;

  // Query decompression alignment requirements
  nvcompAlignmentRequirements_t decompression_alignment_reqs;
  nvcompStatus_t status = nvcompBatchedGdeflateDecompressGetRequiredAlignments(
    decompress_opts,
    &decompression_alignment_reqs);
  if (status != nvcompSuccess) {
    throw std::runtime_error("ERROR: nvcompBatchedGdeflateDecompressGetRequiredAlignments() not successful");
  }

  // Copy compressed data to GPU
  BatchData compressed_data(compressed_data_cpu, true, decompression_alignment_reqs.input);

  // Allocate and build up decompression batch on GPU
  BatchData decomp_data(input_data_cpu, false, decompression_alignment_reqs.output);

  // Create CUDA stream
  cudaStream_t stream;
  CUDA_CHECK(cudaStreamCreate(&stream));

  // CUDA events to measure decompression time
  cudaEvent_t start, end;
  CUDA_CHECK(cudaEventCreate(&start));
  CUDA_CHECK(cudaEventCreate(&end));

  // Gdeflate GPU decompression
  size_t decomp_temp_bytes;
  status = nvcompBatchedGdeflateDecompressGetTempSizeAsync(
      chunk_count,
      chunk_size,
      decompress_opts,
      &decomp_temp_bytes,
      chunk_count * chunk_size);
  if (status != nvcompSuccess) {
    throw std::runtime_error("ERROR: nvcompBatchedGdeflateDecompressGetTempSizeAsync() not successful");
  }

  void* d_decomp_temp;
  CUDA_CHECK(cudaMallocSafe(&d_decomp_temp, decomp_temp_bytes));

  size_t* d_decomp_sizes;
  CUDA_CHECK(cudaMallocSafe(&d_decomp_sizes, chunk_count * sizeof(size_t)));

  nvcompStatus_t* d_statuses;
  CUDA_CHECK(cudaMallocSafe(&d_statuses, chunk_count * sizeof(nvcompStatus_t)));

  CUDA_CHECK(cudaStreamSynchronize(stream));

  auto perform_decompression = [&]() {
    if (nvcompBatchedGdeflateDecompressAsync(
          compressed_data.ptrs(),
          compressed_data.sizes(),
          decomp_data.sizes(),
          d_decomp_sizes,
          chunk_count,
          d_decomp_temp,
          decomp_temp_bytes,
          decomp_data.ptrs(),
          decompress_opts,
          d_statuses,
          stream) != nvcompSuccess) {
      throw std::runtime_error("ERROR: nvcompBatchedGdeflateDecompressAsync() not successful");
    }
  };

  // Run warm-up decompression
  for (size_t iter = 0; iter < warmup_iteration_count; ++iter) {
    perform_decompression();
  }

  // Re-run decompression to get throughput
  CUDA_CHECK(cudaEventRecord(start, stream));
  for (size_t iter = warmup_iteration_count; iter < total_iteration_count; ++iter) {
    perform_decompression();
  }
  CUDA_CHECK(cudaEventRecord(end, stream));
  CUDA_CHECK(cudaStreamSynchronize(stream));

  // Validate decompressed data against input
  if (!(input_data_cpu == decomp_data)) {
    throw std::runtime_error("Failed to validate decompressed data");
  } else {
