    const int  nthreads = 128;
    const int  nblocks  = (batches + nthreads - 1) / nthreads;
    kernel<<<nblocks, nthreads, 0, stream>>>(d_A, d_B, d_info, batches);
    CUDA_CHECK_AND_EXIT(hipGetLastError());
    CUDA_CHECK_AND_EXIT(hipStreamSynchronize(stream));

    CUDA_CHECK_AND_EXIT(cudaMemcpyAsync(L.data(), d_A, sizeof(data_type) * A.size(), hipMemcpyDeviceToHost, stream));
    CUDA_CHECK_AND_EXIT(cudaMemcpyAsync(X.data(), d_B, sizeof(data_type) * B.size(), hipMemcpyDeviceToHost, stream));
    CUDA_CHECK_AND_EXIT(cudaMemcpyAsync(info.data(), d_info, sizeof(int) * info.size(), hipMemcpyDeviceToHost, stream));

    CUDA_CHECK_AND_EXIT(hipStreamSynchronize(stream));
    if (std::accumulate(info.begin(), info.end(), 0) != 0) {
        std::cout << "non-zero d_info returned for at least one of the batches after cuSolverDx kernel \n";
        for (int j = 0; j < info.size(); j++) {
