    const auto     one_batch_size_b_gmem = (cusolverdx::arrangement_of_v_b<Solver> == cusolverdx::col_major) ? ldb_gmem * k : max_mn * ldb_gmem;
    constexpr auto lda_smem              = Solver::lda;
