            decltype(Size<32, 16, 14>() + Precision<float>() + Type<type::complex>() + Function<unmqr>() +
                     Arrangement<arrangement::row_major, arrangement::row_major>() + TransposeMode<conj_trans>() + Side<side::right>() + SM<Arch>() + Block());
    using Solver = decltype(Base() + BatchesPerBlock<Base::suggested_batches_per_block>());

