__global__ __launch_bounds__(Solver::max_threads_per_block) void kernel(DataType*                     d,
                                                                        DataType*                     e,
                                                                        DataType*                     U,
                                                                        DataType*                     VT,
                                                                        typename Solver::status_type* info,
                                                                        const unsigned                batches) {
