    CUDA_CHECK_AND_EXIT(hipStreamSynchronize(stream));

    CUDA_CHECK_AND_EXIT(cudaMemcpyAsync(X.data(), d_B, sizeof(data_type) * B.size(), hipMemcpyDeviceToHost, stream));
    CUDA_CHECK_AND_EXIT(hipStreamSynchronize(stream));

