                          cublasdx::Block() + cublasdx::BlockDim<NT>() + cublasdx::SM<Arch>());

    // left-looking, out of core algorithm

    unsigned n_tiles = N / NB;
    int rinfo = 0;


    for (int k = 0; k < n_tiles; ++k) {
