    // Compare results
    //=========================
    const auto total_relative_error = common::check_error<data_type, data_type>(L.data(), A.data(), A.size());
    std::cout << "Relative forward error of A between cuSolverDx and cuSolver results: " << total_relative_error << std::endl;

