                                          size_t offset,
                                          void *callerInfo,
                                          void *sharedPtr) {
    static constexpr float scale = 1.0 / fft_size;

    cufftComplex value = static_cast<cufftComplex*>(dataIn)[offset];
    value.x *= scale;
    value.y *= scale;
    return value;
}

