    CUDA_CHECK_AND_EXIT(hipMemcpy(output_host.data(), output, Batches * flat_fft_size_bytes, hipMemcpyDeviceToHost));
    CUDA_CHECK_AND_EXIT(hipDeviceSynchronize());

