                 cublasdx::Type<cublasdx::type::complex>() + cublasdx::Function<cublasdx::function::MM>() +
                 cublasdx::Arrangement<arrangement_a, arrangement_b>() + cublasdx::Block() + cublasdx::SM<Arch>());

