        cublasdx::copy_wait();
        if (threadIdx.z == 0) {
            BLAS().execute(alpha, a_shared_tensor, b_shared_tensor, beta, c_shared_tensor);
        }
        __syncthreads();
        if (threadIdx.z == 0) {
            cublasdx::copy<BLAS, alignment::c>(c_shared_tensor, out_global_tensor);
        }
    }
