    extern __shared__ __align__(16) cublasdx::byte smem[];

    auto a_global_tensor   = cublasdx::make_tensor(a, BLAS::get_layout_gmem_a());
    auto b_global_tensor   = cublasdx::make_tensor(b, BLAS::get_layout_gmem_b());
