        decltype(cublasdx::Size<m, n, k>() + cublasdx::Precision<__half>() + cublasdx::Type<cublasdx::type::real>() +
                 cublasdx::Arrangement<cublasdx::row_major, cublasdx::row_major>() +
                 cublasdx::LeadingDimension<lda, ldb, ldc>() + cublasdx::Function<cublasdx::function::MM>() +
