    CUDA_CHECK_AND_EXIT(cudaMallocManaged(&output, global_c_size * sizeof(value_type)));

    // Fill the input matrix
    auto host_a = example::get_random_data<value_type>(global_a_size);
    for (size_t i = 0; i < host_a.size(); i++) {
        host_a[i] = i + 1;
    }
