    auto host_a = example::get_random_data<value_type>(global_a_size);
    for (size_t i = 0; i < host_a.size(); i++) {
        host_a[i] = i + 1;
    }
    CUDA_CHECK_AND_EXIT(
        hipMemcpy(a_matrix, host_a.data(), global_a_size * sizeof(value_type), hipMemcpyHostToDevice));
    CUDA_CHECK_AND_EXIT(hipDeviceSynchronize());

    // Increase max dynamic shared memory for the kernel if needed
    const auto shared_memory_size =
        cublasdx::make_shared_storage_calculator()
            .add(cublasdx::alignment_of_v_a<BLAS>, sizeof(value_type), BLAS::get_layout_smem_a())
            .get();
