        static_assert(std::is_convertible_v<b_io_value_type, b_compute_value_type>);
        auto host_b_compute = std::vector<b_compute_value_type>(host_b_io.begin(), host_b_io.end());

        static_assert(std::is_convertible_v<c_io_value_type, c_compute_value_type>);
        auto host_c_compute = std::vector<c_compute_value_type>(host_c_io.begin(), host_c_io.end());

        CUDA_CHECK_AND_EXIT(
            hipMemcpy(a_cublasdx, host_a_io.data(), m * k * sizeof(a_io_value_type), hipMemcpyHostToDevice));
        CUDA_CHECK_AND_EXIT(
            hipMemcpy(b_cublasdx, host_b_io.data(), k * n * sizeof(b_io_value_type), hipMemcpyHostToDevice));
        CUDA_CHECK_AND_EXIT(
            hipMemcpy(c_cublasdx, host_c_io.data(), m * n * sizeof(c_io_value_type), hipMemcpyHostToDevice));

        CUDA_CHECK_AND_EXIT(
            hipMemcpy(a_cublas, host_a_compute.data(), m * k * sizeof(a_compute_value_type), hipMemcpyHostToDevice));
        CUDA_CHECK_AND_EXIT(
            hipMemcpy(b_cublas, host_b_compute.data(), k * n * sizeof(b_compute_value_type), hipMemcpyHostToDevice));
        CUDA_CHECK_AND_EXIT(
