    blas2_host_c.assign(blas1_reference_host_output.begin(), blas1_reference_host_output.end());
    auto reference_host_output = example::reference_gemm<BLAS2>(alpha2, blas2_host_c, host_d, beta2, host_f);

    // Check against reference
    if (example::check_error<BLAS2>(host_output, reference_host_output)) {
        std::cout << "Success" << std::endl;
        return 0;
    }
    std::cout << "Failure" << std::endl;
    return 1;
}

struct simple_gemm_functor {
    template<int Arch, cublasdx::sm_modifier Modifier>
    int operator()(std::integral_constant<int, Arch>, std::integral_constant<cublasdx::sm_modifier, Modifier>) {
        return simple_gemm<Arch>();
    }
};

int main(int, char**) {
