    print_matrix(n, rank, V.data() + strideV, ldv);
    std::printf("=====\n");

    ds_sup = 0;
    for (int j = 0; j < n; j++) {
        float err = fabs(S[strideS + j] - S_exact[strideS + j]);
        ds_sup = (ds_sup > err) ? ds_sup : err;
