    std::vector<double> U(ldu * m * batchSize, 0); /* U = [U0 ; U1] */
    std::vector<double> V(ldv * n * batchSize, 0); /* V = [V0 ; V1] */
    std::vector<double> S(minmn * batchSize, 0);   /* S = [S0 ; S1] */
