     *        |  1  -1   0 |
     *   A0 = | -1   2   0 |
     *        |  0   0   0 |
     *
     *   A0 = V0 * W0 * V0**T
     *
     *   W0 = diag(0, 0.3820, 2.6180)
     *
     *        |  3   4  0 |
     *   A1 = |  4   7  0 |
     *        |  0   0  0 |
     *
     *   A1 = V1 * W1 * V1**T
     *
     *   W1 = diag(0, 0.5279, 9.4721)
     *
     */

    std::vector<double> A(lda * m * batchSize, 0); /* V = [A0 ; A1] */
    std::vector<double> V(lda * m * batchSize, 0); /* V = [V0 ; V1] */
