float median(std::vector<float> &times) {
    const size_t size = times.size();
    if (size == 0) {
        return 0;
    }

    std::sort(times.begin(), times.end());

    const size_t mid = size / 2;
    if (size % 2 == 0) {
        return (times[mid] + times[mid - 1]) / 2;
    } else {
        return times[mid];
    }
}

