                               stream));
    CUDA_CHECK(cudaMemcpyAsync(d_B, B.data(), sizeof(data_type) * B.size(), cudaMemcpyHostToDevice,
                               stream));

    /* step 3: compute */
    CUBLAS_CHECK(
        cublasDsymm(cublasH, side, uplo, m, n, &alpha, d_A, lda, d_B, ldb, &beta, d_C, ldc));

