            printf("C[%d]\n", j);
            print_matrix(m_array[i], n_array[i], C_array[problem_idx].data(),
                         ldc_array[i]);
            printf("=====\n");

            problem_idx++;
        }
        if (i < group_count - 1) {
            printf("\n");
        }
    }

