    rocblas_handle cublasH = NULL;
    hipStream_t stream = NULL;

    // Compute with 7 INT8 slices
    int mantissaBitCount = 55;

    // Disables the automatic dynamic precision tuning framework
    cudaEmulationMantissaControl_t mControl = CUDA_EMULATION_MANTISSA_CONTROL_FIXED;

    const int m = 2;
    const int n = 2;
    const int k = 2;
    const int lda = 2;
    const int ldb = 2;
    const int ldc = 2;

    /*
     *   A = | 1.0 | 3.0 |
     *       | 2.0 | 4.0 |
     *
     *   B = | 5.0 | 7.0 |
     *       | 6.0 | 8.0 |
     */
    const std::vector<double> A = {1.0, 2.0, 3.0, 4.0};
    const std::vector<double> B = {5.0, 6.0, 7.0, 8.0};
    std::vector<double> C(m * n);
    const double alpha = 1.0;
    const double beta = 0.0;

    double *d_A = nullptr;
    double *d_B = nullptr;
    double *d_C = nullptr;

    void* workspace;
    size_t workspaceSizeInBytes;

    cublasOperation_t transa = CUBLAS_OP_N;
    cublasOperation_t transb = CUBLAS_OP_N;

    printf("A\n");
    print_matrix(m, k, A.data(), lda);
    printf("=====\n");

    printf("B\n");
    print_matrix(k, n, B.data(), ldb);
    printf("=====\n");

    /* Step 1: Create cuBLAS handle and bind a stream */
    CUBLAS_CHECK(rocblas_create_handle(&cublasH));

    CUDA_CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CUBLAS_CHECK(cublasSetStream(cublasH, stream));

